<!--
  Ficheiro: src/components/iptv/ChannelSourcesDialog.vue
  Tipo: Diálogo Vue autónomo.
  Função: Carrega e gere fontes alternativas sem depender do detalhe do canal.
-->
<script setup lang="ts">
import { ref,watch } from "vue";import { iptvSourceRepository } from "@/domain/repositories";import type { ChannelRecord,StreamLinkRecord } from "@/types/records";import StreamLinkManager from "./StreamLinkManager.vue";import StreamPlayerDialog from "./StreamPlayerDialog.vue";
const props=defineProps<{channel:ChannelRecord|null;open:boolean}>();const emit=defineEmits<{close:[];channelChanged:[ChannelRecord]}>();const links=ref<StreamLinkRecord[]>([]),loading=ref(false),error=ref(""),playerOpen=ref(false);async function load(){if(!props.channel)return;loading.value=true;error.value="";try{const result=await iptvSourceRepository.list({page:1,perPage:100,filter:`canal_tv = "${props.channel.id}"`,sort:"prioridade"});links.value=result.items}catch(c){error.value=c instanceof Error?c.message:String(c)}finally{loading.value=false}}watch(()=>[props.open,props.channel?.id] as const,([open])=>{if(open)void load()},{immediate:true});
</script>
<template><Teleport to="body"><div v-if="open&&channel" class="dialog-backdrop" @click.self="emit('close')"><section class="dialog-panel channel-sources-dialog" role="dialog" aria-modal="true" aria-labelledby="channel-sources-title" @keydown.esc="emit('close')"><div class="dialog-header"><div><p class="eyebrow">{{channel.nome}}</p><h2 id="channel-sources-title">Streams principal e alternativos</h2></div><button class="icon-button" type="button" aria-label="Fechar fontes" @click="emit('close')">×</button></div><section class="source-main-card"><span>Stream principal atual</span><code>{{channel.url_stream}}</code><small>Ao tornar uma alternativa principal, este endereço é atualizado automaticamente.</small></section><div v-if="error" class="form-alert form-alert-error" role="alert">{{error}}</div><div v-if="loading" class="page-loading" aria-live="polite">A carregar fontes…</div><StreamLinkManager v-else :channel="channel" :links="links" @changed="links=$event" @channel-changed="emit('channelChanged',$event)" @play="playerOpen=true"/><StreamPlayerDialog :channel="channel" :links="links" :open="playerOpen" @close="playerOpen=false"/></section></div></Teleport></template>
